  storageGet(key) {
    return this.window.localStorage.getItem(key);
  }

  describeList() {
    const labels = this.visibleLis().map((li) => this.labelOf(li));
    const all = this.allLis().map((li) => this.labelOf(li) + (li.hidden ? ' (hidden)' : ''));
    return 'visible=[' + labels.join(', ') + '] all=[' + all.join(', ') + ']';
