const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '..', '..');
const INDEX_HTML = path.join(ROOT, 'index.html');
const APP_JS = path.join(ROOT, 'js', 'app.js');
const APP_CSS = path.join(ROOT, 'css', 'app.css');

// A fresh happy-dom window loaded with the production index.html and js/app.js.
// Each scenario starts from a clean window; reloads re-seed localStorage and hash.
class TodoWorld {
  constructor({ attach, parameters }) {
    this.attach = attach;
    this.parameters = parameters;
    this.window = null;
    this.document = null;
  }

  // Load the app into a fresh window. `seed` is a plain object of localStorage
  // keys to values; `hash` is a route fragment like '#/active'.
  loadApp({ seed, hash } = {}) {
    const route = hash || '';
    const window = new Window({ url: 'http://localhost/' + route });
    // Self-references so production code that uses `window` resolves.
    window.window = window;
    window.self = window;
    window.globalThis = window;

    if (seed) {
      for (const [k, v] of Object.entries(seed)) {
        window.localStorage.setItem(k, v);
      }
    }

    const html = fs.readFileSync(INDEX_HTML, 'utf8');
    window.document.write(html);
    window.document.close();

    if (fs.existsSync(APP_JS)) {
      const code = fs.readFileSync(APP_JS, 'utf8');
      const sandbox = window;
      try {
        vm.createContext(sandbox);
      } catch (e) {
        // already a context
      }
      vm.runInContext(code, sandbox, { filename: 'js/app.js' });
    }

    this.window = window;
    this.document = window.document;

    // Fire lifecycle events the app may listen for.
    this.window.document.dispatchEvent(new this.window.Event('DOMContentLoaded'));
    this.window.dispatchEvent(new this.window.Event('load'));
  }


